use crate::personnel::{Personnel, PersonnelDraft};
use std::{collections::HashMap, fs::File, io::{Read, Write}, path::Path};
use zip::{write::SimpleFileOptions, ZipArchive, ZipWriter};

pub const KEYS: &[&str] = &["rank","surname","given_name","patronymic","position","tax_id","birth_date","education_level","education_details","armed_forces_service_start_date","position_assigned_date","position_assignment_order","military_id","assigned_vehicle_name","assigned_vehicle_registration","full_name","passport_series","passport_number","passport_issued_by","passport_issue_date","foreign_passport","foreign_passport_issued_by","foreign_passport_issue_date","foreign_passport_series","foreign_passport_number","military_document_issued_by","military_document_issue_date","combatant_certificate","combatant_certificate_issued_by","combatant_certificate_issue_date","combatant_certificate_series","combatant_certificate_number","driver_license","driver_license_issued_by","driver_license_categories","driver_license_valid_until","driver_license_issue_date","driver_license_series","driver_license_number","basic_military_training","basic_training_start_date","basic_training_end_date","basic_training_location","phone","email","marital_status","blood_type","military_fitness","oath_date","service_type","service_start_date","conscription_institution"];
fn esc(s:&str)->String{s.replace('&',"&amp;").replace('<',"&lt;").replace('>',"&gt;")}
fn col(mut n:usize)->String{let mut s=String::new();loop{ s.insert(0,(b'A'+(n%26)as u8)as char);if n<26{break}n=n/26-1;}s}
fn value(p:&Personnel,k:&str)->String{match k{"rank"=>p.rank.clone(),"surname"=>p.surname.clone(),"given_name"=>p.given_name.clone(),"patronymic"=>p.patronymic.clone(),"position"=>p.position.clone(),"tax_id"=>p.tax_id.clone(),"birth_date"=>p.birth_date.clone(),"education_level"=>p.education_level.clone(),"education_details"=>p.education_details.clone(),"armed_forces_service_start_date"=>p.armed_forces_service_start_date.clone(),"position_assigned_date"=>p.position_assigned_date.clone(),"position_assignment_order"=>p.position_assignment_order.clone(),"military_id"=>p.military_id.clone(),"assigned_vehicle_name"=>p.assigned_vehicle_name.clone(),"assigned_vehicle_registration"=>p.assigned_vehicle_registration.clone(),"full_name"=>p.full_name.clone(),_=>p.core_fields.get(k).cloned().unwrap_or_default()}}
fn label(key:&str)->String { match key { "rank"=>"Звання", "surname"=>"Прізвище", "given_name"=>"Ім’я", "patronymic"=>"По батькові", "position"=>"Посада", "tax_id"=>"ІПН", "birth_date"=>"Дата народження", "education_level"=>"Формат освіти", "education_details"=>"Де отримана освіта", "armed_forces_service_start_date"=>"У ЗСУ з", "position_assigned_date"=>"Дата призначення", "position_assignment_order"=>"Наказ про призначення", "military_id"=>"Військовий квиток", "assigned_vehicle_name"=>"Автомобіль", "assigned_vehicle_registration"=>"Номер автомобіля", _ => crate::database::STANDARD_EXTRA_FIELDS.iter().find(|(field,_)| *field == key).map(|(_,name)| *name).unwrap_or(key) }.to_string() }
pub fn export(path:&Path, people:&[Personnel])->Result<(),String>{let mut z=ZipWriter::new(File::create(path).map_err(|e|e.to_string())?);let o=SimpleFileOptions::default();z.start_file("[Content_Types].xml",o).unwrap();z.write_all(b"<Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/><Override PartName=\"/xl/worksheets/sheet1.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/></Types>").unwrap();z.start_file("_rels/.rels",o).unwrap();z.write_all(br#"<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>"#).unwrap();z.start_file("xl/_rels/workbook.xml.rels",o).unwrap();z.write_all(br#"<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>"#).unwrap();z.start_file("xl/workbook.xml",o).unwrap();z.write_all("<workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets><sheet name=\"Особовий склад\" sheetId=\"1\" r:id=\"rId1\"/></sheets></workbook>".as_bytes()).unwrap();z.start_file("xl/worksheets/sheet1.xml",o).unwrap();let mut rows=String::new();for r in 0..(people.len()+2){let mut cells=String::new();for(c,k)in KEYS.iter().enumerate(){let v=if r==0{label(k)}else if r==1{k.to_string()}else{value(&people[r-2],k)};cells.push_str(&format!("<c r=\"{}{}\" t=\"inlineStr\"><is><t>{}</t></is></c>",col(c),r+1,esc(&v)));}rows.push_str(&format!("<row r=\"{}\">{}</row>",r+1,cells));}z.write_all(format!("<worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><sheetData>{}</sheetData></worksheet>",rows).as_bytes()).unwrap();z.finish().map_err(|e|e.to_string())?;Ok(())}
fn unescape(value:&str)->String { value.replace("&amp;", "&").replace("&lt;", "<").replace("&gt;", ">") }
fn shared_strings(archive:&mut ZipArchive<File>)->Vec<String> { let Ok(mut file)=archive.by_name("xl/sharedStrings.xml") else { return Vec::new(); }; let mut xml=String::new(); if file.read_to_string(&mut xml).is_err(){return Vec::new();} xml.split("<si>").skip(1).map(|item| item.split("</si>").next().unwrap_or("").split("<t>").skip(1).filter_map(|part|part.split("</t>").next()).map(unescape).collect::<String>()).collect() }
fn cells(row:&str, shared:&[String])->Vec<String>{row.split("<c ").skip(1).map(|cell|{if let Some(text)=cell.split("<t>").nth(1).and_then(|part|part.split("</t>").next()){return unescape(text)} let value=cell.split("<v>").nth(1).and_then(|part|part.split("</v>").next()).unwrap_or(""); if cell.contains("t=\"s\""){return value.parse::<usize>().ok().and_then(|index|shared.get(index)).cloned().unwrap_or_default()} unescape(value)}).collect()}
pub fn import(path:&Path)->Result<Vec<PersonnelDraft>,String>{let f=File::open(path).map_err(|_|"Не вдалося відкрити Excel-файл.".to_string())?;let mut z=ZipArchive::new(f).map_err(|_|"Файл має пошкоджений формат XLSX.".to_string())?;let shared=shared_strings(&mut z);let mut xml=String::new();z.by_name("xl/worksheets/sheet1.xml").map_err(|_|"Відсутній аркуш особового складу.".to_string())?.read_to_string(&mut xml).map_err(|_|"Не вдалося прочитати Excel-файл.".to_string())?;let rows=xml.split("<row ").skip(1).filter_map(|r|r.split("</row>").next()).map(|row|cells(row,&shared)).collect::<Vec<_>>();if rows.len()<2{return Err("Потрібні два рядки заголовків: назви та ключі.".into())}let keys=rows[1].clone();let mut out=Vec::new();for row in rows.into_iter().skip(2){let mut m=HashMap::new();for(i,k)in keys.iter().enumerate(){m.insert(k.clone(),row.get(i).cloned().unwrap_or_default());}if m.values().all(|v|v.trim().is_empty()){continue}let full=m.remove("full_name").unwrap_or_default();let p=full.split_whitespace().collect::<Vec<_>>();let surname=m.remove("surname").filter(|s|!s.is_empty()).unwrap_or_else(||p.first().unwrap_or(&"").to_string());let given=m.remove("given_name").filter(|s|!s.is_empty()).unwrap_or_else(||p.get(1).unwrap_or(&"").to_string());let patron=m.remove("patronymic").filter(|s|!s.is_empty()).unwrap_or_else(||p.get(2).unwrap_or(&"").to_string());let get=|k:&str|m.get(k).cloned().unwrap_or_default();let mut core=m.clone();core.remove("rank");core.remove("position");core.remove("tax_id");let d=PersonnelDraft{rank:get("rank"),surname,given_name:given,patronymic:patron,position:get("position"),tax_id:get("tax_id"),birth_date:get("birth_date"),education_level:get("education_level"),education_details:get("education_details"),armed_forces_service_start_date:get("armed_forces_service_start_date"),position_assigned_date:get("position_assigned_date"),position_assignment_order:get("position_assignment_order"),military_id:get("military_id"),assigned_vehicle_name:get("assigned_vehicle_name"),assigned_vehicle_registration:get("assigned_vehicle_registration"),gender:String::new(),core_fields:core};out.push(d)}Ok(out)}

#[cfg(test)]
mod tests { use super::*; #[test] fn writes_a_valid_xlsx_archive() { let path=std::env::temp_dir().join(format!("raportgen-export-{}.xlsx",std::process::id())); let p=Personnel{id:1,rank:"Солдат".into(),full_name:"Тест Іван Іванович".into(),surname:"Тест".into(),given_name:"Іван".into(),patronymic:"Іванович".into(),position:"Стрілець".into(),tax_id:"1234567890".into(),birth_date:String::new(),education_level:String::new(),education_details:String::new(),armed_forces_service_start_date:String::new(),position_assigned_date:String::new(),position_assignment_order:String::new(),military_id:String::new(),assigned_vehicle_name:String::new(),assigned_vehicle_registration:String::new(),gender:String::new(),core_fields:HashMap::new(),custom_fields:HashMap::new()}; export(&path,&[p]).unwrap(); let f=File::open(&path).unwrap(); assert!(ZipArchive::new(f).unwrap().by_name("xl/worksheets/sheet1.xml").is_ok()); let _=std::fs::remove_file(path); } }
